initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStoreId = '';
  let editingProductId = null;

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#select-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品データを読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        currentProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        renderProductTable();
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // 商品テーブルを描画
  function renderProductTable() {
    const tbody = container.querySelector('#product-table-body');
    if (!currentProducts.length) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; color: var(--text-muted);">商品データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = currentProducts.map(product => `
      <tr data-id="${product.商品ID}">
        <td style="color: var(--text);">${product.商品名 || ''}</td>
        <td><input type="number" class="input current-stock" value="0" min="0" style="width: 80px;"></td>
        <td><input type="number" class="input safety-stock" value="10" min="0" style="width: 80px;"></td>
        <td><input type="number" class="input lead-time" value="${product.リードタイム日数 || 7}" min="1" max="365" style="width: 80px;"></td>
        <td class="forecast-demand" style="color: var(--text);">-</td>
        <td><input type="number" class="input weather-impact" value="50" min="0" max="100" style="width: 80px;"></td>
        <td><input type="number" class="input season-factor" value="1.0" min="0" step="0.1" style="width: 80px;"></td>
        <td class="ai-recommended" style="color: var(--text); font-weight: bold;">-</td>
        <td><input type="number" class="input manual-adjust" value="0" min="0" style="width: 80px;"></td>
        <td class="final-order" style="color: var(--text); font-weight: bold;">-</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${product.商品ID}">詳細</button>
        </td>
      </tr>
    `).join('');

    // 入力フィールドの変更イベント
    tbody.querySelectorAll('input').forEach(input => {
      input.addEventListener('input', calculateOrderQuantity);
      input.addEventListener('blur', calculateOrderQuantity);
    });
  }

  // 発注量計算
  function calculateOrderQuantity() {
    const rows = container.querySelectorAll('#product-table-body tr[data-id]');

    rows.forEach(row => {
      const currentStock = parseInt(row.querySelector('.current-stock').value) || 0;
      const safetyStock = parseInt(row.querySelector('.safety-stock').value) || 0;
      const leadTime = parseInt(row.querySelector('.lead-time').value) || 7;
      const weatherImpact = parseInt(row.querySelector('.weather-impact').value) || 50;
      const seasonFactor = parseFloat(row.querySelector('.season-factor').value) || 1.0;
      const manualAdjust = parseInt(row.querySelector('.manual-adjust').value) || 0;

      // 基本需要予測（簡易計算）
      const baseDemand = Math.floor(Math.random() * 100) + 50; // 実際はAI予測値

      // 天候・季節影響を考慮した需要予測
      const weatherAdjusted = baseDemand * (weatherImpact / 100);
      const seasonAdjusted = weatherAdjusted * seasonFactor;
      const forecastDemand = Math.round(seasonAdjusted);

      // AI推奨発注量計算
      const leadTimeDemand = Math.round(forecastDemand * (leadTime / 7));
      const aiRecommended = Math.max(0, leadTimeDemand + safetyStock - currentStock);

      // 最終発注量（手動調整適用）
      const finalOrder = manualAdjust > 0 ? manualAdjust : aiRecommended;

      // 結果を表示
      row.querySelector('.forecast-demand').textContent = forecastDemand;
      row.querySelector('.ai-recommended').textContent = aiRecommended;
      row.querySelector('.final-order').textContent = finalOrder;
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }

    // 未来日のみの期間チェック
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (new Date(startDate) > today && new Date(endDate) > today) {
      showError('対象期間に過去または現在の日付を含めてください');
      return false;
    }

    return true;
  }

  // 入力値バリデーション
  function validateFieldInputs() {
    const inputs = container.querySelectorAll('#product-table-body input[type="number"]');
    let hasError = false;

    inputs.forEach(input => {
      const value = parseFloat(input.value);
      const min = parseFloat(input.getAttribute('min'));
      const max = parseFloat(input.getAttribute('max'));

      if (isNaN(value)) {
        showError('数値を入力してください');
        input.focus();
        hasError = true;
        return;
      }

      if (min !== null && value < min) {
        if (input.classList.contains('current-stock')) {
          showError('現在在庫数は0以上の値を入力してください');
        } else if (input.classList.contains('lead-time') && max && value > max) {
          showError('リードタイムは1日から365日の範囲で入力してください');
        } else if (input.classList.contains('weather-impact')) {
          showError('天候影響度は0%から100%の範囲で入力してください');
        } else if (input.classList.contains('season-factor') && value < 0) {
          showError('季節補正係数は0以上の値を入力してください');
        } else if (input.classList.contains('manual-adjust')) {
          showError('手動調整値は0以上の値を入力してください');
        }
        input.focus();
        hasError = true;
        return;
      }

      if (max !== null && value > max) {
        if (input.classList.contains('lead-time')) {
          showError('リードタイムは1日から365日の範囲で入力してください');
        } else if (input.classList.contains('weather-impact')) {
          showError('天候影響度は0%から100%の範囲で入力してください');
        }
        input.focus();
        hasError = true;
        return;
      }
    });

    return !hasError;
  }

  // CSVエクスポート
  function exportCSV() {
    const rows = container.querySelectorAll('#product-table-body tr[data-id]');
    if (!rows.length) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品名', '現在在庫数', '安全在庫', 'リードタイム', '需要予測', '天候影響度', '季節補正係数', 'AI推奨発注量', '手動調整', '最終発注量'];
    let csvContent = '\uFEFF' + headers.join(',') + '\n';

    rows.forEach(row => {
      const data = [
        `"${row.cells[0].textContent}"`,
        row.querySelector('.current-stock').value,
        row.querySelector('.safety-stock').value,
        row.querySelector('.lead-time').value,
        row.querySelector('.forecast-demand').textContent,
        row.querySelector('.weather-impact').value,
        row.querySelector('.season-factor').value,
        row.querySelector('.ai-recommended').textContent,
        row.querySelector('.manual-adjust').value,
        row.querySelector('.final-order').textContent
      ];
      csvContent += data.join(',') + '\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const searchTerm = container.querySelector('#input-product-search').value.toLowerCase();
    const category = container.querySelector('#select-category').value;

    let filtered = currentProducts;

    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    if (category) {
      // カテゴリでの絞り込み（実際の実装では商品カテゴリマスタとの結合が必要）
      filtered = filtered.filter(p => {
        // 簡易実装：商品名にカテゴリ名が含まれるかチェック
        return (p.商品名 || '').includes(category);
      });
    }

    const originalProducts = currentProducts;
    currentProducts = filtered;
    renderProductTable();
    currentProducts = originalProducts; // 元のデータを保持
  }

  // モーダル操作
  function openDetailModal(productId) {
    const product = currentProducts.find(p => p.商品ID === productId);
    const row = container.querySelector(`tr[data-id="${productId}"]`);

    if (!product || !row) return;

    editingProductId = productId;
    const modal = container.querySelector('#detail-modal');

    container.querySelector('#modal-product-name').value = product.商品名 || '';
    container.querySelector('#modal-current-stock').value = row.querySelector('.current-stock').value;
    container.querySelector('#modal-safety-stock').value = row.querySelector('.safety-stock').value;
    container.querySelector('#modal-lead-time').value = row.querySelector('.lead-time').value;
    container.querySelector('#modal-weather-impact').value = row.querySelector('.weather-impact').value;
    container.querySelector('#modal-season-factor').value = row.querySelector('.season-factor').value;
    container.querySelector('#modal-manual-adjust').value = row.querySelector('.manual-adjust').value;

    modal.classList.remove('hidden');
  }

  function closeDetailModal() {
    container.querySelector('#detail-modal').classList.add('hidden');
    editingProductId = null;
  }

  function saveModalChanges() {
    if (!editingProductId) return;

    const row = container.querySelector(`tr[data-id="${editingProductId}"]`);
    if (!row) return;

    // バリデーション
    const currentStock = parseInt(container.querySelector('#modal-current-stock').value);
    const safetyStock = parseInt(container.querySelector('#modal-safety-stock').value);
    const leadTime = parseInt(container.querySelector('#modal-lead-time').value);
    const weatherImpact = parseInt(container.querySelector('#modal-weather-impact').value);
    const seasonFactor = parseFloat(container.querySelector('#modal-season-factor').value);
    const manualAdjust = parseInt(container.querySelector('#modal-manual-adjust').value);

    if (currentStock < 0) {
      showError('現在在庫数は0以上の値を入力してください');
      return;
    }
    if (safetyStock < 0) {
      showError('安全在庫は0以上の値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1日から365日の範囲で入力してください');
      return;
    }
    if (weatherImpact < 0 || weatherImpact > 100) {
      showError('天候影響度は0%から100%の範囲で入力してください');
      return;
    }
    if (seasonFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return;
    }
    if (manualAdjust < 0) {
      showError('手動調整値は0以上の値を入力してください');
      return;
    }

    // 値を更新
    row.querySelector('.current-stock').value = currentStock;
    row.querySelector('.safety-stock').value = safetyStock;
    row.querySelector('.lead-time').value = leadTime;
    row.querySelector('.weather-impact').value = weatherImpact;
    row.querySelector('.season-factor').value = seasonFactor;
    row.querySelector('.manual-adjust').value = manualAdjust;

    closeDetailModal();
    calculateOrderQuantity();
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', () => {
    if (!validateInputs()) return;
    if (!validateFieldInputs()) return;

    const rows = container.querySelectorAll('#product-table-body tr[data-id]');
    if (!rows.length) {
      showError('計算対象の商品がありません');
      return;
    }

    calculateOrderQuantity();
  });

  container.querySelector('#btn-forecast-update').addEventListener('click', () => {
    if (!validateInputs()) return;
    calculateOrderQuantity();
  });

  container.querySelector('#btn-product-search').addEventListener('click', filterProducts);

  container.querySelector('#btn-filter-apply').addEventListener('click', filterProducts);

  container.querySelector('#input-product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      filterProducts();
    }
  });

  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  container.querySelector('#btn-create-order').addEventListener('click', () => {
    window.showScreen('scr-1778591907544');
  });

  // モーダル関連イベント
  container.querySelector('#btn-modal-cancel').addEventListener('click', closeDetailModal);
  container.querySelector('#btn-modal-save').addEventListener('click', saveModalChanges);

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      openDetailModal(detailBtn.dataset.id);
    }

    // モーダル背景クリックで閉じる
    if (e.target.id === 'detail-modal') {
      closeDetailModal();
    }
  });

  // 初期化
  loadStores();
  loadProducts();

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#input-start-date').value = weekAgo;
  container.querySelector('#input-end-date').value = today;
}
